import{_ as o,o as a,c as s,a0 as t}from"./chunks/framework.CNXp-E7Q.js";const u=JSON.parse('{"title":"Releasing","description":"","frontmatter":{},"headers":[],"relativePath":"reference/releasing.md","filePath":"reference/releasing.md"}'),r={name:"reference/releasing.md"};function c(n,e,d,i,h,p){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="releasing" tabindex="-1">Releasing <a class="header-anchor" href="#releasing" aria-label="Permalink to &quot;Releasing&quot;">​</a></h1><p>Seeded once, then push-driven. <code>bupha deploy release</code> publishes every workspace member in dependency order and pushes the <code>{repo}-v{ver}</code> seed tag — publishing is the only irreversible step, so it stays explicit. From then on, <code>bupha watch</code> sees pushes to <code>9aia/bupha</code>, queues latest-wins, and runs <code>scripts/release.sh</code> in a worktree (<code>runner.kind = &quot;script&quot;</code>, <code>cancel_running = true</code> — the 5-min sleep inside the script is the debounce window).</p><p>The script diffs since the last tag, patch-bumps and <code>cargo publish</code>es only touched crates (cli republishes on any change), tags <code>bupha-vX</code>, then builds host-arch binaries with <code>cargo dist</code> and uploads them to a GitHub Release via <code>gh</code>.</p><p>Needs on the host: <code>cargo-edit</code> (<code>cargo set-version</code>), <code>cargo-dist</code>, <code>gh</code>, and <code>CARGO_REGISTRY_TOKEN</code> — via env, OS keyring (<code>secret-tool</code>), or <code>~/.config/bupha/env</code>. No GitHub Actions anywhere — releases are just another bupha job. Other build architectures join via the remote-runner pair (TODO.md).</p>',4)])])}const g=o(r,[["render",c]]);export{u as __pageData,g as default};
